return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ur','project-id-version'=>'babilim-0.1.0-ur-babilim-0.1.0-ur-20261030T034656','pot-creation-date'=>'2026-10-30T06:25:47+00:00','po-revision-date'=>'2026-10-30T06:25:47+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'آپ کی سائٹ پر پہلے سے انسٹال شدہ پلگ انز اور تھیمز کے لیے غائب ترجمے مکمل کرتا ہے۔','Translations'=>'ترجمے','Babilim Settings'=>'Babilim ترتیبات','Settings'=>'ترتیبات','You are not allowed to do this.'=>'آپ کو یہ کام کرنے کی اجازت نہیں ہے۔','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'کم اجزاء منتخب کریں: ہر رن میں زیادہ سے زیادہ %1$d آپریشنز (آپ نے %2$d منتخب کیے)۔','That component is not installed on this site, so a translation cannot be requested for it.'=>'یہ جزو اس سائٹ پر انسٹال نہیں ہے، اس لیے اس کے لیے ترجمے کی درخواست نہیں کی جا سکتی۔','Already installed.'=>'پہلے سے انسٹال ہے۔','Downloaded and installed.'=>'ڈاؤن لوڈ اور انسٹال ہو گیا۔','Babilim has not been enabled for this site yet.'=>'Babilim ابھی تک اس سائٹ کے لیے فعال نہیں کیا گیا ہے۔','No build is available to download for this locale.'=>'اس زبان کے لیے ڈاؤن لوڈ کے لیے کوئی بلڈ دستیاب نہیں ہے۔','Rolled back to the previous build.'=>'پچھلے بلڈ پر واپس لے جایا گیا۔','Rolled back and reported.'=>'واپس لے جایا گیا اور رپورٹ کر دیا گیا۔','Rolled back, but the report could not be sent: %s'=>'واپس لے جایا گیا، لیکن رپورٹ نہیں بھیجی جا سکی: %s','Removed.'=>'ہٹا دیا گیا۔','Translation requested.'=>'ترجمے کی درخواست کر دی گئی۔','This component was already uploaded. Babilim is checking it now.'=>'یہ جزو پہلے ہی اپ لوڈ ہو چکا ہے۔ Babilim اب اسے چیک کر رہا ہے۔','Upload cancelled.'=>'اپ لوڈ منسوخ کر دیا گیا۔','Upload complete — translation requested.'=>'اپ لوڈ مکمل — ترجمے کی درخواست کر دی گئی۔','This component does not declare a version number, so a translation cannot be requested for it.'=>'اس جزو میں ورژن نمبر درج نہیں ہے، اس لیے اس کے لیے ترجمے کی درخواست نہیں کی جا سکتی۔','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'اس جزو کا ورژن نمبر %d حروف سے زیادہ لمبا ہے، جسے Babilim سنبھال نہیں سکتا، اس لیے اس کے لیے ترجمے کی درخواست نہیں کی جا سکتی۔','A translation cannot be requested for that locale on this site right now.'=>'اس سائٹ پر ابھی اس زبان کے لیے ترجمے کی درخواست نہیں کی جا سکتی۔','Thank you. Your report was sent.'=>'شکریہ۔ آپ کی رپورٹ بھیج دی گئی ہے۔','This report does not name a valid plugin or theme and locale.'=>'اس رپورٹ میں کسی درست پلگ ان یا تھیم اور زبان کا نام درج نہیں ہے۔','Please choose a category for this report.'=>'براہ کرم اس رپورٹ کے لیے ایک زمرہ منتخب کریں۔','This report is missing a valid build to report against.'=>'اس رپورٹ میں رپورٹ کرنے کے لیے کوئی درست بلڈ موجود نہیں ہے۔','This build is not one this site currently knows about for this component/locale.'=>'یہ بلڈ ایسا نہیں ہے جسے یہ سائٹ اس جزو/زبان کے لیے اس وقت جانتی ہو۔','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'فیلڈ "%1$s" بہت لمبی ہے: اس میں %2$d حروف ہیں اور حد %3$d ہے۔ کچھ نہیں بھیجا گیا؛ براہ کرم اسے مختصر کریں اور دوبارہ کوشش کریں۔','Original string'=>'اصل سٹرنگ','String context'=>'سٹرنگ کا سیاق','Current translation'=>'موجودہ ترجمہ','Suggested translation'=>'تجویز کردہ ترجمہ','Note (optional)'=>'نوٹ (اختیاری)','Where you saw this (optional)'=>'آپ نے یہ کہاں دیکھا (اختیاری)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim کی مطابقت پذیری سروس کی جانب سے عارضی طور پر تاخیر کا شکار ہے (شرح محدود)؛ یہ %s کے بعد دوبارہ کوشش کرے گی۔','The locale you added is not valid: use a WordPress locale code such as ll_CC (letters, digits, underscore, hyphen or @, at most %d characters). Nothing was saved.'=>'آپ کی شامل کردہ زبان درست نہیں ہے: ll_CC جیسا WordPress لوکیل کوڈ استعمال کریں (حروف، ہندسے، انڈر اسکور، ہائفن یا @، زیادہ سے زیادہ %d حروف)۔ کچھ محفوظ نہیں کیا گیا۔','Settings saved.'=>'ترتیبات محفوظ ہو گئیں۔','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'اگر یہ آن ہے تو ان انسٹال کرنے پر اس سائٹ کی شناخت بھی مٹ جائے گی۔ اس سائٹ سے منسلک ادائیگی شدہ لائسنس بعد میں خودکار طور پر بحال نہیں کیا جا سکے گا؛ اسے واپس حاصل کرنے کے لیے آپ کو Babilim سپورٹ سے %s پر رابطہ کرنا ہوگا۔','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim کو ترتیب دیا گیا ہے کہ پلگ ان حذف ہونے پر اس سائٹ کی شناخت مٹا دے۔ اس سائٹ سے منسلک ادائیگی شدہ لائسنس پھر خودکار طور پر بحال نہیں کیا جا سکے گا؛ آپ کو Babilim سپورٹ سے %s پر رابطہ کرنا ہوگا۔ شناخت برقرار رکھنے کے لیے منسوخ کریں دبائیں، Babilim ترتیبات میں "ان انسٹال کرتے وقت Babilim کا تمام ڈیٹا حذف کریں" کا نشان ہٹائیں، اور دوبارہ غیر فعال کریں۔ پھر بھی غیر فعال کریں؟','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'اس نیٹ ورک کی %1$d سائٹ کو ترتیب دیا گیا ہے کہ پلگ ان حذف ہونے پر اپنی Babilim شناخت مٹا دے۔ اس سائٹ سے منسلک ادائیگی شدہ لائسنس پھر خودکار طور پر بحال نہیں کیا جا سکے گا؛ آپ کو Babilim سپورٹ سے %2$s پر رابطہ کرنا ہوگا۔ شناخت برقرار رکھنے کے لیے منسوخ کریں دبائیں، اس سائٹ کی Babilim ترتیبات میں "ان انسٹال کرتے وقت Babilim کا تمام ڈیٹا حذف کریں" کا نشان ہٹائیں، اور دوبارہ غیر فعال کریں۔ پھر بھی غیر فعال کریں؟' . "\0" . 'اس نیٹ ورک کی %1$d سائٹس کو ترتیب دیا گیا ہے کہ پلگ ان حذف ہونے پر اپنی Babilim شناخت مٹا دیں۔ ان سائٹس سے منسلک ادائیگی شدہ لائسنس پھر خودکار طور پر بحال نہیں کیے جا سکیں گے؛ آپ کو Babilim سپورٹ سے %2$s پر رابطہ کرنا ہوگا۔ شناختیں برقرار رکھنے کے لیے منسوخ کریں دبائیں، ہر سائٹ کی Babilim ترتیبات میں "ان انسٹال کرتے وقت Babilim کا تمام ڈیٹا حذف کریں" کا نشان ہٹائیں، اور دوبارہ غیر فعال کریں۔ پھر بھی غیر فعال کریں؟','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'اس نیٹ ورک میں سائٹس کی تعداد اتنی زیادہ ہے کہ انہیں ایک ایک کر کے چیک نہیں کیا جا سکتا، اور ہو سکتا ہے ان میں سے کچھ پر پلگ اِن حذف ہونے کے وقت Babilim کی شناخت مٹانے کی سیٹنگ لگی ہو۔ ایسی سائٹ سے منسلک ادائیگی شدہ لائسنس پھر خودبخود بحال نہیں ہو سکے گا؛ آپ کو %s پر Babilim سپورٹ سے رابطہ کرنا پڑے گا۔ شناختیں برقرار رکھنے کے لیے منسوخ کریں دبائیں، ہر سائٹ کی Babilim ترتیبات میں "ان انسٹال کرتے وقت Babilim کا تمام ڈیٹا حذف کریں" کا نشان ہٹائیں، اور دوبارہ غیر فعال کریں۔ پھر بھی غیر فعال کریں؟','Open Babilim settings'=>'Babilim ترتیبات کھولیں','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim اس سائٹ کی توثیق نہیں کر سکا، اس لیے کچھ بھی ڈاؤن لوڈ یا انسٹال نہیں کیا گیا۔','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'سروس آپ کی سائٹ تک نہیں پہنچ سکی۔ غالباً کوئی فائر وال، سیکیورٹی پلگ اِن یا ہوسٹ کا اصول درخواست کو روک رہا ہے؛ براہ کرم /wp-json/babilim/v1/challenge کی درخواستوں کی اجازت دیں۔','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'آپ کی سائٹ نے جواب دینے میں بہت دیر کی۔ براہ کرم بعد میں دوبارہ کوشش کریں، اور دیکھ لیں کہ آپ کا ہوسٹ بہت سست یا اوورلوڈ تو نہیں۔','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'آپ کی سائٹ نے جواب دیا، لیکن توقع کے مطابق نہیں۔ ممکن ہے REST API کو کسی دوسرے پلگ اِن نے تبدیل کر دیا ہو، یا وہ اینڈ پوائنٹ کیش ہو رہا ہو؛ براہ کرم /wp-json/babilim/v1/challenge کو کیشنگ اور ری رائٹنگ سے مستثنیٰ کریں۔','Please check that your site can be reached from the internet, then try again.'=>'براہ کرم دیکھ لیں کہ آپ کی سائٹ انٹرنیٹ سے قابل رسائی ہے، پھر دوبارہ کوشش کریں۔','Re-verify'=>'دوبارہ توثیق کریں','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'یہ سائٹ اس حد سے بڑی ہے جو سروس ایک سنک میں قبول کرتی ہے، اس لیے کچھ آئٹمز چھوڑ دیے گئے: %1$d اجزاء اور %2$d زبانیں۔','This site is verified.'=>'اس سائٹ کی توثیق ہو چکی ہے۔','Registration restarted.'=>'رجسٹریشن دوبارہ شروع کی گئی۔','Sync complete.'=>'سنک مکمل ہو گیا۔','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim اس سائٹ کو فعال اور چیک کر رہا ہے… یہ صفحہ دوبارہ لوڈ کریں یا طے شدہ چیک مکمل ہونے کا انتظار کریں۔','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim فعال ہونے کا عمل مکمل نہیں کر سکا (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'جو ہوسٹ ایک وقت میں صرف ایک PHP درخواست سنبھالتا ہے وہ یہ مرحلہ مکمل نہیں کر سکتا۔','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim فعال ہے: اس سائٹ کی توثیق ہو گئی اور %d جزو ملا۔' . "\0" . 'Babilim فعال ہے: اس سائٹ کی توثیق ہو گئی اور %d اجزاء ملے۔','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim غیر فعال ہے۔ مزید کچھ نہیں بھیجا جائے گا؛ پہلے سے انسٹال شدہ ترجمے کام کرتے رہیں گے۔','Supplementary translation index rebuilt.'=>'اضافی ترجمہ انڈیکس دوبارہ بنایا گیا۔','Sweep complete: %d file deleted.'=>'صفائی مکمل ہو گئی: %d فائل حذف کی گئی۔' . "\0" . 'صفائی مکمل ہو گئی: %d فائلیں حذف کی گئیں۔','Removed %d installed component.'=>'%d انسٹال شدہ جزو ہٹایا گیا۔' . "\0" . '%d انسٹال شدہ اجزاء ہٹائے گئے۔','Automatic installs are now off; turn them on again in the settings if you want them.'=>'خودکار انسٹالیشنز اب بند ہیں؛ اگر چاہیں تو ترتیبات میں انہیں دوبارہ آن کریں۔','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim اس سائٹ کے وہ پلگ اِنز اور تھیمز تلاش کرتا ہے جن کا آپ کی زبان میں ترجمہ موجود نہیں، اور ہر ایک کے لیے ایک ترجمہ انسٹال کرتا ہے۔','Languages found on this site: %s.'=>'اس سائٹ پر پائی گئی زبانیں: %s۔','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'دستیاب ترجمے ایک کلک سے انسٹال کیے جا سکتے ہیں، اور غائب ترجموں کی درخواست کی جا سکتی ہے۔ اس کے بعد نئے ترجمے اور اپ ڈیٹس خودکار طور پر انسٹال ہوتے ہیں (مفت پلان پر صرف ان پلگ اِنز اور تھیمز کے لیے جو پہلے ہی مفت سلاٹ استعمال کر رہے ہوں)۔','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'مفت پلان محدود تعداد میں پلگ اِنز اور تھیمز کا احاطہ کرتا ہے؛ Babilim فعال کرنے کے بعد آپ کا درست کوٹہ ترتیبات میں دکھایا جائے گا۔','What is sent when you enable Babilim'=>'Babilim فعال کرنے پر کیا بھیجا جاتا ہے','Enabling…'=>'فعال کیا جا رہا ہے…','Enable Babilim'=>'Babilim فعال کریں','By clicking Enable, you agree to send the information listed above to Babilim.'=>'فعال کریں پر کلک کر کے آپ اوپر درج معلومات Babilim کو بھیجنے سے اتفاق کرتے ہیں۔','Check again now'=>'ابھی دوبارہ چیک کریں','Babilim installed %d translation automatically since your last visit.'=>'آپ کی پچھلی وزٹ کے بعد سے Babilim نے %d ترجمہ خودکار طور پر انسٹال کیا۔' . "\0" . 'آپ کی پچھلی وزٹ کے بعد سے Babilim نے %d ترجمے خودکار طور پر انسٹال کیے۔','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim اس سائٹ کو فعال اور چیک کر رہا ہے… (آخری کوشش: %s)','Check again'=>'دوبارہ چیک کریں','No components synced yet.'=>'ابھی تک کوئی جزو سنک نہیں ہوا۔','%d succeeded'=>'%d کامیاب' . "\0" . '%d کامیاب','%d skipped'=>'%d چھوڑے گئے' . "\0" . '%d چھوڑے گئے','%d failed'=>'%d ناکام' . "\0" . '%d ناکام','%d not yet tried'=>'%d کی ابھی کوشش نہیں ہوئی' . "\0" . '%d کی ابھی کوشش نہیں ہوئی','Bulk %s:'=>'بلک %s:','%1$s nothing to do.'=>'%1$s کرنے کو کچھ نہیں۔','%1$s %2$s.'=>'%1$s %2$s۔','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'جاری ہے…','Continue next batch (%d left)'=>'اگلا بیچ جاری رکھیں (%d باقی)','Search components'=>'اجزاء تلاش کریں','These are the languages this site uses. You can change them in %s.'=>'یہ وہ زبانیں ہیں جو یہ سائٹ استعمال کرتی ہے۔ آپ انہیں %s میں تبدیل کر سکتے ہیں۔','Upload this component?'=>'کیا یہ جزو اپ لوڈ کریں؟','There is no upload waiting for confirmation.'=>'تصدیق کا منتظر کوئی اپ لوڈ نہیں ہے۔','Back'=>'واپس','To translate this component, Babilim needs its source.'=>'اس جزو کا ترجمہ کرنے کے لیے Babilim کو اس کا سورس درکار ہے۔','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'%1$s (ورژن %2$s) کی پوری پلگ اِن یا تھیم ڈائریکٹری Babilim پر اپ لوڈ کی جائے گی۔','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'اگر اس ڈائریکٹری میں کیز، لاگز یا کسٹمر ڈیٹا موجود ہو تو وہ بھی اپ لوڈ ہو جائے گا۔ سروس عام حساس فائلیں (کنفیگریشن، ماحول، ڈیٹابیس ڈمپ، لاگز، کیز) ہٹا دیتی ہے مگر یہ ضمانت نہیں دے سکتی کہ وہ سب کچھ ڈھونڈ لے گی۔','The upload is kept until you ask Babilim to delete it.'=>'اپ لوڈ اس وقت تک رکھا جاتا ہے جب تک آپ Babilim سے اسے حذف کرنے کو نہ کہیں۔','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'اسے سروس کا ہوسٹنگ فراہم کنندہ محفوظ رکھتا ہے اور ترجمہ تیار کرنے کے لیے AI ماڈلز اسے پروسیس کرتے ہیں۔','The original text and the translations made from it will be provided to other sites that install the same version.'=>'اصل متن اور اس سے تیار کردہ تراجم ان دیگر سائٹس کو فراہم کیے جائیں گے جو یہی ورژن انسٹال کرتی ہیں۔','By continuing you confirm that you have the right to upload this component.'=>'جاری رکھ کر آپ تصدیق کرتے ہیں کہ آپ کو یہ جزو اپ لوڈ کرنے کا حق حاصل ہے۔','Upload and request'=>'اپ لوڈ کریں اور درخواست دیں','Uploading…'=>'اپ لوڈ ہو رہا ہے…','Cancel'=>'منسوخ کریں','Uploading'=>'اپ لوڈ ہو رہا ہے','There is no upload in progress.'=>'کوئی اپ لوڈ جاری نہیں ہے۔','Uploading part %1$d of %2$d…'=>'حصہ %1$d از %2$d اپ لوڈ ہو رہا ہے…','Continue'=>'جاری رکھیں','Confirm'=>'تصدیق کریں','Remove'=>'ہٹائیں','Roll back'=>'واپس لیں','Nothing to confirm.'=>'تصدیق کے لیے کچھ نہیں۔','Choose a language'=>'زبان منتخب کریں','Roll back and report'=>'واپس لیں اور رپورٹ کریں','Report a problem'=>'مسئلے کی رپورٹ کریں','Nothing to choose.'=>'منتخب کرنے کے لیے کچھ نہیں۔','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s۔ زبان منتخب کریں۔','Supplementary translations'=>'اضافی تراجم','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'ہر جزو کا اپنا حصہ ہر لوکیل کے مشترکہ ڈیفالٹ ڈومین سپلیمنٹ میں۔','Component'=>'جزو','Language'=>'زبان','Included in index'=>'انڈیکس میں شامل','Entries'=>'اندراجات','Conflicting keys'=>'متصادم کیز','Yes'=>'ہاں','No — component inactive'=>'نہیں — جزو غیر فعال ہے','No — installed version differs from the active one'=>'نہیں — انسٹال شدہ ورژن فعال ورژن سے مختلف ہے','No — component removed'=>'نہیں — جزو ہٹا دیا گیا ہے','No'=>'نہیں','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'یہ کام صرف نیٹ ورک ایڈمنسٹریٹر کر سکتا ہے، کیونکہ اس سے ترجمے کی وہ فائلیں تبدیل ہوتی ہیں جو اس نیٹ ورک کی تمام سائٹس میں مشترک ہیں۔','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim اس سائٹ کی توثیق مکمل نہیں کر سکا (سروس اس تک واپس رسائی حاصل نہیں کر سکی)۔ رجسٹریشن روک دی گئی ہے۔','This site already has an active registration that can no longer be recovered automatically.'=>'اس سائٹ کی ایک فعال رجسٹریشن پہلے سے موجود ہے جو اب خودکار طور پر بحال نہیں کی جا سکتی۔','Restart registration'=>'رجسٹریشن دوبارہ شروع کریں','Babilim settings'=>'Babilim ترتیبات','General'=>'عمومی','Advanced'=>'اعلیٰ','Languages'=>'زبانیں','Automatic installs'=>'خودکار انسٹالیشنز','Install available translations automatically'=>'دستیاب تراجم خودکار طور پر انسٹال کریں','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'مفت پلان پر صرف وہی اجزا خودکار طور پر انسٹال ہوتے ہیں جو پہلے ہی آپ کے مفت سلاٹس میں سے کوئی ایک استعمال کر رہے ہوں، اس لیے کوئی نیا سلاٹ نہیں لیا جاتا۔','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'یہ سائٹ ایک ملٹی سائٹ نیٹ ورک کا حصہ ہے، جو نئے تراجم خودکار طور پر انسٹال نہیں کرتا۔ پہلے سے انسٹال شدہ تراجم پھر بھی اپ ڈیٹ ہوتے رہتے ہیں۔','Custom overrides'=>'حسبِ ضرورت اوور رائیڈز','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'سب کچھ صاف کرتے وقت یا اس پلگ اِن کو ان انسٹال کرتے وقت میرے اپنے ترجمے کے اوور رائیڈز محفوظ رکھیں۔','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'جو ترجمہ فائلیں آپ %s میں رکھتے ہیں وہ ہمیشہ Babilim کی فائلوں پر فوقیت رکھتی ہیں۔ جب تک آپ اس کا نشان نہ ہٹائیں وہ محفوظ رہتی ہیں۔','Uninstall'=>'ان انسٹال','Delete all Babilim data on uninstall'=>'ان انسٹال کرتے وقت Babilim کا تمام ڈیٹا حذف کریں','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'بطورِ طے شدہ بند: پلگ اِن حذف کرنے پر اس سائٹ کی شناخت محفوظ رہتی ہے، تاکہ دوبارہ انسٹال کرنے پر اسے دوبارہ استعمال کیا جا سکے۔','Account'=>'اکاؤنٹ','Save changes'=>'تبدیلیاں محفوظ کریں','Disable Babilim'=>'Babilim غیر فعال کریں','Installed translations are kept, but no further checks or downloads will run.'=>'انسٹال شدہ تراجم محفوظ رہیں گے، لیکن مزید جانچ یا ڈاؤن لوڈ نہیں ہوں گے۔','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim غیر فعال کریں؟ انسٹال شدہ تراجم محفوظ رہیں گے، لیکن مزید جانچ یا ڈاؤن لوڈ نہیں ہوں گے۔','This site is not registered with Babilim yet.'=>'یہ سائٹ ابھی تک Babilim کے ساتھ رجسٹر نہیں ہے۔','This site is already licensed. Reload the page.'=>'اس سائٹ کو پہلے ہی لائسنس مل چکا ہے۔ صفحہ دوبارہ لوڈ کریں۔','Checkout is not available for this site right now.'=>'اس وقت اس سائٹ کے لیے چیک آؤٹ دستیاب نہیں ہے۔','Could not start checkout: %s'=>'چیک آؤٹ شروع نہیں ہو سکا: %s','Babilim is not enabled.'=>'Babilim فعال نہیں ہے۔','Not registered yet'=>'ابھی تک رجسٹر نہیں ہوا','Not verified'=>'تصدیق شدہ نہیں','Verified'=>'تصدیق شدہ','Status'=>'اسٹیٹس','Licensed'=>'لائسنس یافتہ','Partner'=>'پارٹنر','Free'=>'مفت','License'=>'لائسنس','Upgrade this site'=>'اس سائٹ کو اپ گریڈ کریں','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'اس سائٹ کے لیے یک وقتی خریداری: %1$s %2$s۔ اس میں مستقبل کی تمام ترجمہ اپ ڈیٹس شامل ہیں۔ ادائیگی Paddle کے ذریعے نئے ٹیب میں کی جاتی ہے۔','This issues a new restore code and the previous one stops working. Continue?'=>'اس سے نیا بحالی کوڈ جاری ہوگا اور پچھلا کوڈ کام کرنا بند کر دے گا۔ جاری رکھیں؟','Show a new restore code'=>'نیا بحالی کوڈ دکھائیں','rc_…'=>'rc_…','Restore code'=>'بحالی کوڈ','Restore purchase'=>'خریداری بحال کریں','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'کیا آپ نے اس ڈومین کے لیے پہلے لائسنس خریدا تھا؟ چیک آؤٹ پر موصول ہونے والا بحالی کوڈ درج کریں۔','That does not look like a restore code.'=>'یہ بحالی کوڈ جیسا نہیں لگتا۔','This restore code was not recognised for this site.'=>'یہ بحالی کوڈ اس سائٹ کے لیے پہچانا نہیں گیا۔','Too many attempts. Try again tomorrow.'=>'بہت زیادہ کوششیں۔ کل دوبارہ کوشش کریں۔','This site must be verified first.'=>'پہلے اس سائٹ کی تصدیق ضروری ہے۔','Could not restore the purchase: %s'=>'خریداری بحال نہیں کی جا سکی: %s','Purchase restored. This site is now licensed.'=>'خریداری بحال ہو گئی۔ اب یہ سائٹ لائسنس یافتہ ہے۔','This site has no purchase to show a code for.'=>'اس سائٹ کی کوئی خریداری نہیں ہے جس کا کوڈ دکھایا جا سکے۔','Could not show a new restore code: %s'=>'نیا بحالی کوڈ نہیں دکھایا جا سکا: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'آپ کا نیا بحالی کوڈ: %s۔ اسے کسی محفوظ جگہ رکھیں — پچھلا کوڈ اب کام نہیں کرتا۔','What is sent when Babilim checks this site'=>'Babilim جب اس سائٹ کو چیک کرتا ہے تو کیا بھیجا جاتا ہے','(detected)'=>'(شناخت شدہ)','No language is managed yet.'=>'ابھی تک کوئی زبان زیر انتظام نہیں ہے۔','Babilim adds translations for every language checked here.'=>'Babilim یہاں منتخب کی گئی ہر زبان کے لیے ترجمے شامل کرتا ہے۔','Add another language'=>'ایک اور زبان شامل کریں','Choose a language…'=>'زبان منتخب کریں…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'سروس سے WordPress.org کی مکمل لوکیل فہرست لوڈ نہیں ہو سکی، اس لیے اس وقت کوئی اور زبان شامل نہیں کی جا سکتی۔','Theme'=>'تھیم','Plugin'=>'پلگ ان','Free quota'=>'مفت کوٹہ','Downloads: %1$d/%2$d (%3$s)'=>'ڈاؤن لوڈز: %1$d/%2$d (%3$s)','Supplementary translation index'=>'اضافی ترجمہ انڈیکس','Built'=>'تیار شدہ','Included'=>'شامل','Excluded'=>'خارج','Already in WordPress core'=>'WordPress کور میں پہلے سے موجود','Supplementary translation maintenance'=>'اضافی ترجمہ کی دیکھ بھال','Maintenance status is not available right now.'=>'دیکھ بھال کا اسٹیٹس اس وقت دستیاب نہیں ہے۔','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s پر صفائی روک دی گئی: %2$s۔ کچھ بھی حذف نہیں کیا گیا۔','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'آخری صفائی %1$s پر: نئی نشان زد کی گئی فائلوں کی تعداد: %2$d، حذف کی گئی فائلوں کی تعداد: %3$d، ہٹائے گئے ریکارڈز کی تعداد: %4$d۔','No cleanup has run yet.'=>'ابھی تک کوئی صفائی نہیں چلی۔','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'ترجمہ انڈیکس کی ایک تحریر %1$s پر دوسری درخواست سے ٹکرا گئی (%2$s) اور لاگو نہیں ہوئی؛ تازہ ترین ورژن برقرار رکھا گیا۔','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'ترجمہ انڈیکس کی %1$s پر تحریر (%2$s) مکمل نہ ہو سکی اور لاگو نہیں ہوئی (%3$s)۔','Maintenance'=>'دیکھ بھال','Rebuild index now'=>'انڈیکس ابھی دوبارہ بنائیں','Sweep now'=>'ابھی صفائی کریں','Danger zone'=>'خطرناک زون','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'اس سائٹ پر ہر پلگ اِن اور تھیم کے لیے Babilim کی انسٹال کی ہوئی ہر زبان کی فائل ہٹا دیتا ہے۔','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'کیا Babilim کی انسٹال کی ہوئی ہر چیز ہٹا دی جائے؟ اس سے اس سائٹ پر ہر پلگ اِن اور تھیم کے لیے Babilim کی انسٹال کی ہوئی ہر زبان کی فائل حذف ہو جائے گی۔','Remove everything Babilim installed'=>'Babilim کی انسٹال کی ہوئی ہر چیز ہٹائیں','This string is too long to be sent as a report, so no report form is offered for it.'=>'یہ اسٹرنگ رپورٹ کے طور پر بھیجنے کے لیے بہت لمبی ہے، اس لیے اس کے لیے رپورٹ فارم پیش نہیں کیا جاتا۔','Category'=>'زمرہ','Choose a category…'=>'زمرہ منتخب کریں…','Roll back and send report'=>'واپس لیں اور رپورٹ بھیجیں','Send report'=>'رپورٹ بھیجیں','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'اس جزو کا کچھ متن اس کے مصنف نے ہارڈ کوڈ کیا ہے اور لینگویج پیک اس کا ترجمہ نہیں کر سکتا۔','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'تھیم کے ساتھ شامل','Bundled with the plugin'=>'پلگ اِن کے ساتھ شامل','Upload was not accepted'=>'اپ لوڈ قبول نہیں کی گئی','Upload expired before it finished'=>'اپ لوڈ مکمل ہونے سے پہلے ختم ہو گئی','No translation'=>'کوئی ترجمہ نہیں','Upload in progress — continue or cancel'=>'اپ لوڈ جاری ہے — جاری رکھیں یا منسوخ کریں','Scheduled, waiting to be processed'=>'شیڈول کیا گیا، پروسیس ہونے کا منتظر','Translating…'=>'ترجمہ ہو رہا ہے…','Translation failed'=>'ترجمہ ناکام ہو گیا','Free quota used'=>'مفت کوٹہ استعمال ہو چکا','Needs a paid license'=>'ادائیگی شدہ لائسنس درکار ہے','Not supported'=>'اس کی معاونت دستیاب نہیں','Status unknown'=>'اسٹیٹس نامعلوم','translation statusInstalled'=>'انسٹال شدہ','Update available'=>'اپ ڈیٹ دستیاب ہے','Removed after a failed integrity check'=>'سالمیت کی جانچ ناکام ہونے کے بعد ہٹا دیا گیا','Installed · built for %s, new version scheduled'=>'انسٹال شدہ · %s کے لیے بنایا گیا، نیا ورژن شیڈول کیا گیا','Installed · built for a different version, new version scheduled'=>'انسٹال شدہ · مختلف ورژن کے لیے بنایا گیا، نیا ورژن شیڈول کیا گیا','Installed · built for %s, translating the new version…'=>'انسٹال شدہ · %s کے لیے بنایا گیا، نئے ورژن کا ترجمہ ہو رہا ہے…','Installed · built for a different version, translating the new version…'=>'انسٹال شدہ · مختلف ورژن کے لیے بنایا گیا، نئے ورژن کا ترجمہ ہو رہا ہے…','Installed · built for %1$s, this site has %2$s'=>'انسٹال شدہ · %1$s کے لیے بنایا گیا، اس سائٹ پر %2$s ہے','Installed · built for %s'=>'انسٹال شدہ · %s کے لیے بنایا گیا','Installed · built for a different version'=>'انسٹال شدہ · مختلف ورژن کے لیے بنایا گیا','Installed · built for %s, new version failed'=>'انسٹال شدہ · %s کے لیے بنایا گیا، نیا ورژن ناکام رہا','Installed · built for a different version, new version failed'=>'انسٹال شدہ · ایک مختلف ورژن کے لیے بنایا گیا، نیا ورژن ناکام رہا','Installed · built for %s, new version needs a paid license'=>'انسٹال شدہ · %s کے لیے بنایا گیا، نئے ورژن کے لیے ادائیگی شدہ لائسنس درکار ہے','Installed · built for a different version, new version needs a paid license'=>'انسٹال شدہ · ایک مختلف ورژن کے لیے بنایا گیا، نئے ورژن کے لیے ادائیگی شدہ لائسنس درکار ہے','Installed · built for %s, free quota used'=>'انسٹال شدہ · %s کے لیے بنایا گیا، مفت کوٹہ استعمال ہو چکا','Installed · built for a different version, free quota used'=>'انسٹال شدہ · ایک مختلف ورژن کے لیے بنایا گیا، مفت کوٹہ استعمال ہو چکا','translation statusAvailable'=>'دستیاب','Installed · %s'=>'انسٹال شدہ · %s','Available · %s'=>'دستیاب · %s','Update'=>'اپ ڈیٹ کریں','Download'=>'ڈاؤن لوڈ کریں','Updating…'=>'اپ ڈیٹ ہو رہا ہے…','Downloading…'=>'ڈاؤن لوڈ ہو رہا ہے…','Retry request'=>'درخواست دوبارہ کریں','Request newer translation'=>'نئے ترجمے کی درخواست کریں','Request translation'=>'ترجمے کی درخواست کریں','Requesting…'=>'درخواست کی جا رہی ہے…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'ترجمے کی درخواست کرنے سے آپ کا ایک مفت سلاٹ استعمال ہوتا ہے، سوائے اس کے کہ یہ جزو پہلے ہی ایک سلاٹ استعمال کر رہا ہو۔ ناکام ترجمہ سلاٹ واپس نہیں کرتا۔','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'اگر یہ جزو ابھی تک آپ کے مفت سلاٹس میں سے کوئی استعمال نہیں کر رہا، تو ترجمے کی درخواست کرنے سے ایک استعمال ہوگا۔ ناکام ترجمہ سلاٹ واپس نہیں کرتا۔ جاری رکھیں؟','No plugins or themes found.'=>'کوئی پلگ ان یا تھیم نہیں ملا۔','Clear filters'=>'فلٹرز صاف کریں','No components match these filters. %s'=>'کوئی جزو ان فلٹرز سے مطابقت نہیں رکھتا۔ %s','Select all'=>'سب منتخب کریں','All'=>'تمام','Available'=>'دستیاب','Updates'=>'اپ ڈیٹس','Requestable'=>'درخواست کے قابل','Installed'=>'انسٹال شدہ','Plugins'=>'پلگ انز','Themes'=>'تھیمز','All languages'=>'تمام زبانیں','%d to install'=>'%d انسٹال کرنے کے لیے' . "\0" . '%d انسٹال کرنے کے لیے','Language:'=>'زبان:','Bulk actions apply to every matching language of each selected component.'=>'اجتماعی کارروائیاں ہر منتخب جزو کی تمام مطابقت رکھنے والی زبانوں پر لاگو ہوتی ہیں۔','Bulk actions apply only to the selected language of each selected component.'=>'اجتماعی کارروائیاں صرف ہر منتخب جزو کی منتخب زبان پر لاگو ہوتی ہیں۔','Version %s'=>'ورژن %s','Theme · %s'=>'تھیم · %s','Plugin · %s'=>'پلگ ان · %s','Remove the %2$s translation of %1$s from this site?'=>'کیا %1$s کا %2$s زبان میں ترجمہ اس سائٹ سے ہٹا دیں؟','Roll back the %2$s translation of %1$s to the previous build?'=>'کیا %1$s کے %2$s زبان میں ترجمے کو پچھلے بلڈ پر واپس لیں؟','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'رجسٹریشن چیلنج متوقع شکل میں نہیں ہے۔','That is not a valid build identifier.'=>'یہ درست بلڈ شناخت کنندہ نہیں ہے۔','Refusing to write outside the Babilim language-file directory.'=>'Babilim لینگویج فائل ڈائریکٹری سے باہر لکھنے سے انکار کیا جا رہا ہے۔','Could not write the downloaded package to disk.'=>'ڈاؤن لوڈ کیا گیا پیکیج ڈسک پر نہیں لکھا جا سکا۔','Unexpected HTTP %d response.'=>'غیر متوقع HTTP %d جواب۔','This site\'s URL, so the service can verify you own it.'=>'اس سائٹ کا URL، تاکہ سروس تصدیق کر سکے کہ آپ اس کے مالک ہیں۔','Your WordPress version, to serve compatible translation files.'=>'آپ کا WordPress ورژن، تاکہ مطابقت رکھنے والی ترجمہ فائلیں فراہم کی جا سکیں۔','Your PHP version, for compatibility.'=>'آپ کا PHP ورژن، مطابقت کے لیے۔','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'اس پلگ اِن کا اپنا ورژن، تاکہ اگر یہ بات کرنے کے لیے بہت پرانا ہو تو سروس آپ کو اسے اپڈیٹ کرنے کا کہہ سکے۔','This site\'s configured locale.'=>'اس سائٹ کا ترتیب شدہ لوکیل۔','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'اس سائٹ پر استعمال ہونے والا ہر لوکیل (سائٹ لوکیل، انسٹال شدہ لینگویج پیکس، صارف لوکیلز، اور وہ جو آپ دستی طور پر شامل کریں)۔ کسی لوکیل کے ساتھ دوسرے سے مختلف سلوک نہیں کیا جاتا۔','(a public key generated for this site)'=>'(اس سائٹ کے لیے بنائی گئی ایک پبلک کی)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'اس سائٹ کی انسٹال پبلک کی، جو یہ ثابت کرنے کے لیے استعمال ہوتی ہے کہ درخواستیں واقعی اسی سائٹ سے آتی ہیں۔ صرف پبلک حصہ ہی بھیجا جاتا ہے۔','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'ہر انسٹال شدہ پلگ اِن/تھیم: اس کا سلگ، ورژن، ٹیکسٹ ڈومین، آیا یہ wp.org کی لسٹنگ ہے، اس کے اپنے شامل لوکیلز، اور کن لوکیلز کے لیے آپ پہلے ہی Babilim ترجمہ انسٹال کر چکے ہیں۔','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'صرف اس وقت جب آپ ایسے پلگ اِن یا تھیم کے لیے اپ لوڈ کی تصدیق کریں جو WordPress.org پر نہیں ہے: اس جزو کی پوری ڈائریکٹری، زپ کی صورت میں۔','(generic codes and coordinates only)'=>'(صرف عمومی کوڈز اور کوآرڈینیٹس)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'زیادہ سے زیادہ 20 زیر التوا تشخیصی واقعات (مثلاً وہ فائل جو اپنی سالمیت کی جانچ میں ناکام ہوئی)، ہر ایک صرف کوڈ، جزو اور لوکیل پر مشتمل، اور کبھی بھی کوئی اسٹرنگ مواد یا ترجمہ شدہ متن نہیں۔','Unsafe locale: %s'=>'غیر محفوظ لوکیل: %s','Manifest unavailable: %s'=>'مینی فیسٹ دستیاب نہیں: %s','Could not determine active components; the existing merged index was left unchanged.'=>'فعال اجزاء کا تعین نہیں ہو سکا؛ موجودہ مرج شدہ انڈیکس کو تبدیل نہیں کیا گیا۔','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'انسٹال شدہ پلگ اِنز/تھیمز کا تعین نہیں ہو سکا؛ سویپ چھوڑ دیا گیا، کچھ بھی حذف نہیں ہوا۔','Sweep aborted without orphaning anything: %s.'=>'کسی کو بھی یتیم کیے بغیر سویپ روک دیا گیا: %s۔','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'صفائی چلی، لیکن اس کی کچھ تبدیلیاں ترجمہ انڈیکس میں ریکارڈ نہیں ہو سکیں؛ اگلی صفائی انہیں دوبارہ آزمائے گی۔','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' کا مرج شدہ انڈیکس دوبارہ بنایا گیا، لیکن ترجمہ انڈیکس اسے ریکارڈ نہیں کر سکا؛ اگلی دوبارہ تعمیر اسے دوبارہ آزمائے گی۔','Could not write the staged merged index.'=>'اسٹیج کیا گیا مرج شدہ انڈیکس لکھا نہیں جا سکا۔','Re-parsed entry count did not match the built index.'=>'دوبارہ پارس کی گئی اندراجات کی تعداد بنائے گئے انڈیکس سے میل نہیں کھاتی۔','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' کا مرج شدہ انڈیکس اپنی جگہ پر منتقل نہیں ہو سکا؛ پچھلا فراہم کردہ انڈیکس (اگر کوئی تھا) آدھا اپڈیٹ شدہ چھوڑنے کے بجائے ہٹا دیا گیا۔ اگلی کامیاب دوبارہ تعمیر تک اس لوکیل کے لیے کوئی ڈیفالٹ ڈومین سپلیمنٹ فراہم نہیں کیا جائے گا۔','Could not open zip: %s'=>'زپ کھولی نہیں جا سکی: %s','Zip has no manifest.json.'=>'زپ میں manifest.json موجود نہیں ہے۔','manifest.json in the zip is not valid JSON.'=>'زپ میں موجود manifest.json درست JSON نہیں ہے۔','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json کا \'%s\' متوقع قدر سے میل نہیں کھاتا۔','Another installation is running; try again in a moment.'=>'ایک اور انسٹالیشن چل رہی ہے؛ کچھ دیر بعد دوبارہ کوشش کریں۔','Not a valid server_build_id: %s'=>'درست server_build_id نہیں ہے: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'پیکیج مینی فیسٹ کی قسم \'%1$s\' مطلوبہ قسم \'%2$s\' سے میل نہیں کھاتی۔','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'پیکیج کا ٹیکسٹ ڈومین \'%1$s\' اس سائٹ کے جزو کی کاپی (\'%2$s\') سے میل نہیں کھاتا، اس لیے یہ انسٹال نہیں کیا گیا۔','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'دیا گیا ڈومین \'%1$s\' نہ تو پیکیج مینی فیسٹ کے اپنے سلگ \'%2$s\' سے اور نہ ہی اس کے text_domain \'%3$s\' سے میل کھاتا ہے۔','Unsafe slug: %s'=>'غیر محفوظ سلگ: %s','Unsafe text_domain: %s'=>'غیر محفوظ text_domain: %s','The package has no %s for its own text domain.'=>'پیکیج میں اس کے اپنے ٹیکسٹ ڈومین کے لیے %s موجود نہیں ہے۔','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json موجود نہیں ہے یا اس میں \'%s\' غلط ہے۔','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json موجود نہیں ہے یا اس میں \'entries\' غلط ہے۔','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json موجود نہیں ہے یا اس میں \'files\' غلط ہے۔','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json موجود نہیں ہے یا اس میں \'extra_domains\' غلط ہے۔','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json موجود نہیں ہے یا اس میں \'build_no\' غلط ہے۔','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json کا \'server_build_id\' درست بلڈ آئی ڈی نہیں ہے۔','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json کا \'contract\' درست ورژن اسٹرنگ نہیں ہے۔','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json کا \'status\' لازماً \'published\' ہونا چاہیے۔','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json کا \'kind\' لازماً \'plugin\' یا \'theme\' (تھیم) ہونا چاہیے۔','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json میں \'default_domain_entries\' غلط ہے۔','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json میں \'default_domain_files\' غلط ہے۔','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest موجود نہیں ہے یا اس میں \'%s\' غلط ہے۔','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest کا \'server_build_id\' درست بلڈ آئی ڈی نہیں ہے۔','No record for %s'=>'%s کا کوئی ریکارڈ نہیں ملا','One or more served files no longer match the manifest.'=>'ایک یا زیادہ فراہم کردہ فائلیں اب manifest سے مطابقت نہیں رکھتیں۔','No previous build to roll back to.'=>'واپس جانے کے لیے کوئی پچھلا بلڈ موجود نہیں ہے۔','The change could not be recorded in the translation index; please try again.'=>'تبدیلی ترجمہ انڈیکس میں درج نہیں ہو سکی؛ براہ کرم دوبارہ کوشش کریں۔','Unknown kind: %s'=>'نامعلوم kind: %s','Unsafe domain: %s'=>'غیر محفوظ ڈومین: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'ٹیکسٹ ڈومین \'%1$s\' (%2$s) پہلے ہی ایک اور انسٹال شدہ جزو (%3$s) کے لیے فراہم کیا جا رہا ہے؛ کچھ انسٹال نہیں کیا گیا۔','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'واپس جانے سے \'%1$s\' (%2$s) اوور رائٹ ہو جائے گی، جو اب ایک اور انسٹال شدہ جزو (%3$s) کے لیے فراہم کی جا رہی ہے؛ کچھ تبدیل نہیں کیا گیا۔','Zip is missing expected file: %s'=>'زپ میں مطلوبہ فائل موجود نہیں: %s','sha256 mismatch for %s'=>'%s کے لیے sha256 مطابقت نہیں رکھتا','The package declares no main translation file.'=>'پیکیج میں کوئی مرکزی ترجمہ فائل درج نہیں ہے۔','Zip is missing expected default file: %s'=>'زپ میں مطلوبہ ڈیفالٹ فائل موجود نہیں: %s','sha256 mismatch for default/%s'=>'default/%s کے لیے sha256 مطابقت نہیں رکھتا','Could not stage %s'=>'%s کو اسٹیج نہیں کیا جا سکا','Could not stage default/%s'=>'default/%s کو اسٹیج نہیں کیا جا سکا','Entry count mismatch for %s'=>'%s کے لیے اندراجات کی تعداد مطابقت نہیں رکھتی','Could not verify entry count for %s'=>'%s کے اندراجات کی تعداد کی توثیق نہیں ہو سکی','l10n.php entry count mismatch for %s'=>'%s کے لیے l10n.php اندراجات کی تعداد مطابقت نہیں رکھتی','Default supplement entry count mismatch.'=>'ڈیفالٹ سپلیمنٹ کے اندراجات کی تعداد مطابقت نہیں رکھتی۔','The package produced no servable main translation file.'=>'پیکیج سے کوئی قابل فراہمی مرکزی ترجمہ فائل تیار نہیں ہوئی۔','Could not prepare %s for rollback.'=>'%s کو واپسی کے لیے تیار نہیں کیا جا سکا۔','Could not back up %s before replacing it.'=>'%s کو تبدیل کرنے سے پہلے اس کا بیک اپ نہیں لیا جا سکا۔','Could not move %s into place.'=>'%s کو اس کی جگہ پر منتقل نہیں کیا جا سکا۔','English (United States)'=>'انگریزی (ریاستہائے متحدہ)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest دستیاب نہیں ہے: %s','could not read _manifest.json: %s'=>'_manifest.json پڑھا نہیں جا سکا: %s','failed to parse _manifest.json: %s'=>'_manifest.json کو پارس کرنے میں ناکامی: %s','_manifest.json has an unexpected structure'=>'_manifest.json کی ساخت غیر متوقع ہے','Could not create the package archive.'=>'پیکیج آرکائیو نہیں بنایا جا سکا۔','No writable temporary directory is available for packaging.'=>'پیکیجنگ کے لیے کوئی قابلِ تحریر عارضی ڈائریکٹری دستیاب نہیں ہے۔','A file in the component could not be read, so it was not packaged.'=>'جزو کی ایک فائل پڑھی نہیں جا سکی، اس لیے اسے پیکیج نہیں کیا گیا۔','Only plugins and themes can be packaged.'=>'صرف پلگ اِنز اور تھیمز کو پیکیج کیا جا سکتا ہے۔','The component\'s main file was not found.'=>'جزو کی مرکزی فائل نہیں ملی۔','The component is not inside the plugins or themes directory.'=>'جزو پلگ اِنز یا تھیمز کی ڈائریکٹری کے اندر نہیں ہے۔','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim کا اس مرحلے کے لیے وقت ختم ہو گیا اور یہ اگلی جانچ میں جاری رہے گا۔','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim اس سائٹ کی تصدیق نہیں کر سکا، اس لیے تصدیق کامیاب ہونے تک کچھ بھی ڈاؤن لوڈ یا انسٹال نہیں کیا جائے گا۔','Registration response was missing required fields.'=>'رجسٹریشن کے جواب میں مطلوبہ فیلڈز موجود نہیں تھیں۔','No pending challenge to verify.'=>'تصدیق کے لیے کوئی زیرِ التوا چیلنج موجود نہیں۔','Verify response was missing site_token.'=>'تصدیق کے جواب میں site_token موجود نہیں تھا۔','No site id is on file to rotate a token for.'=>'ٹوکن تبدیل کرنے کے لیے فائل میں کوئی سائٹ آئی ڈی محفوظ نہیں ہے۔','Rotate-token response was missing site_token.'=>'ٹوکن تبدیل کرنے کے جواب میں site_token موجود نہیں تھا۔','nonce must be a hexadecimal string.'=>'nonce ایک ہیکساڈیسیمل اسٹرنگ ہونا ضروری ہے۔','No pending challenge for this nonce.'=>'اس nonce کے لیے کوئی زیرِ التوا چیلنج موجود نہیں۔','Too many requests.'=>'بہت زیادہ درخواستیں۔','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'اس سائٹ میں %2$d زبانوں میں %1$d اجزاء ہیں، جن کے لیے %3$d جانچ بیچز درکار ہیں؛ Babilim ہر رن میں زیادہ سے زیادہ %4$d سنبھال سکتا ہے۔ ترتیبات میں منظم زبانیں کم کریں یا غیر استعمال شدہ پلگ اِنز اور تھیمز غیر فعال کریں، پھر اب دوبارہ جانچیں دبائیں۔','Babilim could not finish checking this site.'=>'Babilim اس سائٹ کی جانچ مکمل نہیں کر سکا۔','This site\'s address is too long for Babilim to register.'=>'اس سائٹ کا پتہ Babilim کے رجسٹر کرنے کے لیے بہت لمبا ہے۔','This site\'s locale code is not one Babilim can register.'=>'اس سائٹ کا لوکیل کوڈ ایسا نہیں ہے جسے Babilim رجسٹر کر سکے۔','The download response was missing a usable location.'=>'ڈاؤن لوڈ کے جواب میں قابلِ استعمال مقام موجود نہیں تھا۔','The service\'s upload offer was incomplete.'=>'سروس کی اپ لوڈ پیشکش نامکمل تھی۔','This component is larger than the service accepts, so it cannot be uploaded.'=>'یہ جزو سروس کی قبول کردہ حد سے بڑا ہے، اس لیے اسے اپ لوڈ نہیں کیا جا سکتا۔','The packaged component could not be read.'=>'پیکیج شدہ جزو پڑھا نہیں جا سکا۔','A part of the upload kept failing, so the upload was cancelled.'=>'اپ لوڈ کا ایک حصہ بار بار ناکام ہوتا رہا، اس لیے اپ لوڈ منسوخ کر دیا گیا۔','Could not read: %s'=>'پڑھا نہیں جا سکا: %s']];